import pandas as pd
from itertools import cycle
from random import randint, seed

def task_func(
    n_grades,
    students=['Alice', 'Bob', 'Charlie', 'David', 'Eve'],
    grade_range=range(1, 11),
    rng_seed=None
):
    if not students:
        raise ValueError("List of students is empty.")

    if n_grades < 0:
        raise ValueError("n_grades must be non-negative.")

    grade_values = list(grade_range)
    if not grade_values:
        raise ValueError("grade_range must not be empty.")

    if rng_seed is not None:
        seed(rng_seed)

    student_cycle = cycle(students)
    data = [
        {
            "Student": next(student_cycle),
            "Grade": grade_values[randint(0, len(grade_values) - 1)],
        }
        for _ in range(n_grades)
    ]

    return pd.DataFrame(data, columns=["Student", "Grade"])
